<?php
function rf_recent_history(){echo '<section class="card"><h3>Recent Inspection / Claims Updates</h3>';$items=array_values(rf_journal());usort($items,fn($a,$b)=>$b['event_id']<=>$a['event_id']);$off=max(0,(int)($_GET['claims_offset']??0));$rows=[];$links=[];foreach(array_slice($items,$off,20) as $r){$rows[]=[$r['platform'].' / '.$r['order'],$r['inspection'],$r['claims'],mb_substr($r['remarks'],0,160),$r['recorded_at'].' · '.$r['actor']];$links[]=rf_link($r['platform'],$r['order']);}om_table(['Platform / Order','Inspection','Claims','Remarks','Recorded / By'],$rows,$links);echo rs8_pagination(count($items),$off,20,$_GET,'claims_offset').'</section>';}
function rf_panel(){if(!access_page_allowed('return_followup'))return;$rows=rf_queue();if(isset($_GET['pending_order']))$rows=array_values(array_filter($rows,fn($r)=>(int)($r['target']['o']['id']??0)===(int)$_GET['pending_order']));echo '<section class="card"><div class="page-head"><div><h3>ICO Return / Refund Follow-up</h3><p>Status tags request follow-up. Inspect only physically received items; stock posts once through Inflow.</p></div><a class="btn secondary" href="?page=return_followup">View All / Claims History</a></div>';if(!$rows){echo '<p>No pending return / inspection / claims tasks.</p></section>';return;}$off=max(0,(int)($_GET['pending_offset']??0));$table=[];$links=[];foreach(array_slice($rows,$off,10) as $r){$t=$r['target'];$s=$r['state'];$table[]=[$t['platform'].' / '.$t['order'],$r['reported'],$s['receiving'],$s['inspection'],$s['claims']];$links[]=rf_link($t['platform'],$t['order']);}om_table(['Platform / Order','Platform Status','Physical Receiving','Inspection','Claims Status'],$table,$links);echo rs8_pagination(count($rows),$off,10,$_GET,'pending_offset').'</section>';}
function rf_page(){rf_require();echo '<div class="page-head"><div><a class="back" href="?page=inflow&entry=manual">← Inflow</a><h1>Return / Refund · Inspection &amp; Claims</h1><p>Order ID is the reference. Claim details belong in attachment and remarks. Claims updates never post stock.</p></div></div>';if(empty($_GET['order'])){echo '<section class="card"><h3>Find Order / Return</h3><form method="get" class="row"><input type="hidden" name="page" value="return_followup"><label>Platform<select name="platform">';foreach(om_shops() as $pl=>$shop)echo '<option>'.e($pl).'</option>';echo '</select></label><label>Order ID<input name="order" maxlength="100" required></label><button class="btn secondary">Open Follow-up</button></form></section>';rf_panel();rf_recent_history();return;}$t=rf_target($_GET);$s=rf_state($t);$o=$t['o'];echo '<section class="card"><h3>'.e($t['platform'].' / '.$t['order']).'</h3>';om_table(['Platform Status','Physical Receiving','Inspection','Claims'],[[$o?oa_reported($o)['status']:'No Original Order Record',$s['receiving'],$s['inspection'],$s['claims']]]);if($o)echo '<p><a class="btn ghost" href="?page=order_monitor&order_id='.$o['id'].'">Order / Tracking / History</a></p>';echo '<p>Good Item → Sellable. Damaged / Leak and For Repackaging → Non-Sellable. Wrong Item → Investigation custody; no credit to expected SKU.</p></section>';
 if($o&&($scope=ri_scope($o))){echo '<section class="card"><h3>Tagged Return Items / Quantities</h3>';$expected=[];foreach($scope['totals'] as $pid=>$qty){$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$pid])->fetch();$bal=order_return_balance($t['platform'],$t['order'],$pid);$expected[]=[$p['master_sku'].' · '.$p['name'],$qty,$bal['returned'],max(0,$qty-$bal['returned'])];}om_table(['Product / SKU','Tagged Qty','Received Qty','Still Expected'],$expected);echo '<p>Only these tagged quantities are expected. Other purchased items are not automatically returned.</p></section>';}elseif($o)echo '<p class="alert info">No verified item-level return scope is available. Inspect the original order, then select only the actual received SKU and quantity in Inflow; do not assume the entire order was returned.</p>';
 echo '<section class="card"><h3>Actual Received Items / Stock Effects</h3>';$rows=[];$links=[];foreach($t['receipts'] as $r){$dest=[];if((int)$r['good_qty'])$dest[]='Sellable +'.$r['good_qty'].' · '.$r['platform'];if((int)$r['damaged_qty'])$dest[]='Non-Sellable / Damaged +'.$r['damaged_qty'];if((int)$r['repackaging_qty'])$dest[]='Non-Sellable / Repackaging +'.$r['repackaging_qty'];$rows[]=[$r['master_sku'].' · '.$r['name'],$r['qty'],implode('; ',$dest),$r['batch_ref']];$links[]='<a href="?page=order_return&id='.$r['batch_id'].'">Receipt / Verification</a>';}foreach($t['legacy'] as $r){$rows[]=[$r['master_sku'].' · '.$r['name'],$r['qty'],$r['condition'].' · '.$r['destination'],'Legacy receipt #'.$r['id']];$links[]='<a href="?page=product_detail&id='.$r['product_id'].'">Stock Movements</a>';}om_table(['Product / SKU','Received Qty','Posted Destination','Receipt'],$rows,$links);if(!$rows)echo '<p>No actual return stock has been posted here. Item condition remains pending actual inspection.</p>';foreach($t['wrong'] as $c)echo '<p><a class="btn ghost" href="?page=wrong_returns&id='.$c['id'].'">Wrong Item Case</a> '.e($c['actual_description']).' · '.(int)$c['received_qty'].' held for investigation; expected SKU not credited.</p>';if($o&&$o['posting']==='Posted')echo '<a class="btn secondary" href="?page=inflow&entry=manual&ur_order_id='.$o['id'].'">Receive Actual Items / Choose Condition</a>';echo '<p><a class="btn ghost" href="?page=wrong_returns&view=new">Record Wrong Item Received</a></p></section>';
 if(can_action('return_confirm')){echo '<section class="card"><h3>ICO Inspection / Claims Update</h3><form method="post" action="actions.php" enctype="multipart/form-data" class="stack" data-confirm="Save inspection / claims update? No stock will be added or deducted.">';workflow_hidden('receiving_followup_save',['platform'=>$t['platform'],'order'=>$t['order'],'revision'=>$s['event_id'],'return'=>'return_followup&platform='.rawurlencode($t['platform']).'&order='.rawurlencode($t['order'])]);echo '<div class="grid two"><label>Inspection<select name="inspection">';foreach(['Awaiting Actual Return','For Inspection','Inspected'] as $v)echo '<option'.($v===$s['inspection']?' selected':'').'>'.e($v).'</option>';echo '</select></label><label>Claims Status<select name="claims">';foreach(rf_claims() as $v)echo '<option'.($v===$s['claims']?' selected':'').'>'.e($v).'</option>';echo '</select></label></div><label class="ack"><input type="checkbox" name="physical_ack" value="1"> Item physically received for inspection (no stock posted by this acknowledgement).</label><label>Attachment · Optional<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"></label><label>Remarks<textarea name="remarks" rows="3" minlength="3" maxlength="4000" required>'.e($s['remarks']).'</textarea></label><button class="btn primary">Save Inspection / Claims</button></form></section>';}
 echo '<section class="card"><h3>Inspection / Claims History</h3>';foreach(om_query("SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.event_type='Return follow-up workflow' ORDER BY e.id DESC") as $e){$d=json_decode($e['details_json'],true)?:[];if(($d['key']??'')!==$t['key'])continue;echo '<article class="om-event"><b>'.e($d['inspection'].' · '.$d['claims']).'</b><p>'.e($e['created_at'].' · '.$e['actor']).'</p><p>'.nl2br(e($d['remarks'])).'</p>';if(!empty($d['attachment']))echo '<a class="btn ghost sm" href="return_followup_document.php?event='.(int)$e['id'].'" target="_blank" rel="noopener">View Attachment</a>';echo '<p class="muted small">No stock change.</p></article>';}echo '</section>';}
